package com.company.aiinterview.translation.controller; import com.company.aiinterview.translation.dto.request.TranslationRequestDto; import com.company.aiinterview.translation.dto.response.TranslationResponseDto; import com.company.aiinterview.translation.service.TranslationService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/translation") @RequiredArgsConstructor public class TranslationController { private final TranslationService service; @PostMapping("/text") public TranslationResponseDto translate(@RequestBody TranslationRequestDto request){ return service.translate(request);} }
